                const { pctA, pctB, isBetterA, isBetterB } = computeEffBar(numA, numB, rankNumA, rankNumB);

                const cleanRankA = rankA !== "—" ? (String(rankA).startsWith("#") ? rankA : `#${rankA}`) : "";
